#Requires -Version 7.0
[CmdletBinding(SupportsShouldProcess)]
param()
$ErrorActionPreference='Stop'
$repo='<repo>'
$lane=Join-Path $repo 'docs/evidence/release15/frozen-fdee7a2/live-ui'
$folder=Join-Path $lane 'disabled-input-supplement'
function Get-Pin {
 param([string]$Path)
 [ordered]@{path=$Path;sha256=(Get-FileHash -LiteralPath $Path).Hash;bytes=(Get-Item -LiteralPath $Path).Length}
}
$manifestPath=Join-Path $folder 'manifest.json'
$manifest=Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json -AsHashtable
foreach($copy in $manifest.files){if(-not(Test-Path -LiteralPath $copy.source) -or (Get-FileHash -LiteralPath $copy.retainedCopy).Hash -cne $copy.sha256){throw 'Preserved original/copy verification failed'}}
$runtimePath=Join-Path $lane 'runtime-receipts/live-scale-10.json'
$runtime=Get-Content -LiteralPath $runtimePath -Raw | ConvertFrom-Json -AsHashtable
$uiPath=Join-Path $lane 'runtime-receipts/live-scale-10-failure-ui.json'
$ui=Get-Content -LiteralPath $uiPath -Raw | ConvertFrom-Json -AsHashtable
$nativePath=Join-Path $lane 'live-ui.xml'
[xml]$native=Get-Content -LiteralPath $nativePath -Raw
$failed=@($native.SelectNodes('//testcase[failure or error]'))[0]
$errorText=$failed.SelectSingleNode('failure|error').InnerText
if(-not $errorText.Contains('page.waitForRequest') -or -not $errorText.Contains('toBeEnabled')){throw 'Native failure shape changed'}
$contextPath=@(Get-ChildItem -LiteralPath (Join-Path $lane 'browser-artifacts') -File -Recurse -Filter 'error-context.md')[0].FullName
$actors=@($ui.uiStates | ForEach-Object {
 $body=$_.body
 $solvedMark=[string][char]0x2713
 [ordered]@{player=$_.player;closed=$_.closed;browserConnected=$_.browserConnected;liveConnected=$body.Contains('Live updates connected');roster=([regex]::Match($body,'\d+ / \d+ players')).Value;roundNumbers=@([regex]::Matches($body,'Round\s+(\d+)') | ForEach-Object {$_.Groups[1].Value} | Sort-Object -Unique);pendingGameRetryText=$body.Contains('Retry pending game request');pendingRoomRetryText=$body.Contains('Retry pending room request');hasSubmitAnswer=$body.Contains('Submit answer');solvedScorecardRowCount=@([regex]::Matches($body,([regex]::Escape($solvedMark)+' Solved'))).Count;hasOwnSolvedStatus=$body.Contains($solvedMark+' Solved. Your score is locked');pendingControlEnabled='UNKNOWN: innerText does not encode enabled state'}
})
$slowAnswers=@($runtime.slowResponses | Where-Object {$_.method -eq 'POST' -and $_.action -eq 'answer'} | ForEach-Object {[ordered]@{status=$_.status;durationMs=$_.durationMs;action=$_.action}})
$slowSuccess=@($slowAnswers | Where-Object status -EQ 200)
$sourcePins=@($manifest.files | Where-Object {$_.source.StartsWith((Join-Path $repo 'src/')) -or $_.source.StartsWith((Join-Path $repo 'tests/'))} | ForEach-Object {[ordered]@{path=[IO.Path]::GetRelativePath($repo,$_.source);sha256=$_.sha256;retainedCopy=$_.retainedCopy;currentStillMatches=(Get-FileHash -LiteralPath $_.source).Hash -ceq $_.sha256}})
$effectivePath=$manifest.effectiveSnapshot
$effective=Get-Content -LiteralPath $effectivePath -Raw | ConvertFrom-Json -AsHashtable
$records=@($effective.functional)+@($effective.technical)+@($effective.testing)
$criteria=@(foreach($r in $records | Where-Object id -In @('TR-CONNECTION-RECOVERY-009','TEST-CONNECTIONRECOVERY-109','TR-MULTIPLAYER-INTEGRATION-034','TEST-MULTIPLAYERINTEGRATION-134','TR-ROOM-SYNCRECOVERY-038','TEST-ROOMSYNC-139')){
 foreach($c in $r.acceptanceCriteria | Where-Object id -In @('TR-09-C01','VERIFY-TR-09','TR-34-C01','TR-34-C02','LIVE-05','LIVE-07')){[ordered]@{reference=$r.id+'#'+$c.id;text=$c.text;isSatisfiedAtRead=$c.isSatisfied}}
})
$axes=@(
 [ordered]@{axis='crash_restart_replay';assessment='existing_canonical_recovery_applies';finding='HTTP/driver completion and frontend acknowledgement are separate observers. Retain original command input through actual UI acknowledgement or exact canonical pending retry. Never count a prior command replay as the next requested intent. Existing server idempotence supports recovery but does not prove frontend acknowledgement.';pins=@('game-panel.tsx:173-240','ui-command-capture.ts:42-47')},
 [ordered]@{axis='ordering_concurrency';assessment='confirmed_test_acknowledgement_boundary_gap';finding='Two answer UIs per batch and allSettled remain correct. The helper can return driver JSON while frontend state is still busy/pending; later authoritative view can render a new round without retiring that pending command. No new matching POST is expected while the next UI action remains blocked at its enabled-input precondition. The AggregateError truthfully retains waiter and action timeouts.';pins=@('live-player-counts.integration.spec.ts:146-158','ui-command-capture.ts:10-35','game-panel.tsx:131-136','game-panel.tsx:243-244')},
 [ordered]@{axis='boundary_malformed';assessment='preserve_existing_failure_discrimination';finding='The disabled-input failure is an invoke failure, not a successful-body lookup error. Do not broaden a catch into blind UI retries or fabricate status0. Preserve original errors, absent/disabled pending rejection, full-payload mismatch controls and12attempt bounds. The slow11601.008ms successful response is above source10s signal duration but has no actor/command join.';pins=@('ui-command-capture.ts:43-68','game-panel.tsx:194-209')},
 [ordered]@{axis='supported_host_inert_unsupported';assessment='actual_local_failure_cause_partly_unknown';finding='All10 snapshots retained browser/live connection and full roster. Local source/transport status and runtime resource load cannot be inferred from timing alone. No physical/hosted/tunnel capacity or driver-only cause is established. Another source-load audit is separately owned.';pins=@('native','actorSnapshots','slowAnswerResponses')},
 [ordered]@{axis='lifecycle_terminal';assessment='pending_state_survives_authoritative_refresh';finding='Refresh may advance view and clear error but intentionally does not retire pending. Pending presence alone is sufficient for locked even when a new round is visible; busy and confirmed-version guards are additional independent causes. Only parsed successful mutation or defined terminal denial clears pending. Cleanup0 is preserved; later404 reads appear in the final diagnostic list and cannot override all10 pre-cleanup room snapshots.';pins=@('game-panel.tsx:85-148','game-panel.tsx:173-244','live-player-counts.integration.spec.ts:175-201')},
 [ordered]@{axis='workspace_session_agent_isolation';assessment='explicit_actor_snapshot_not_exact_request_join';finding='uiStates explicitly names player7 for pending text. Native answer input id uses shared roomId, not profile ID. Successful response timing lacks actor,command ID and absolute event timestamp; no content/order/duration join can supply those missing keys. Existing new body-error attribution is empty because this lane observed no driver body errors.';pins=@('game-panel.tsx:450-453','runtime.commandBodyFailures','actorSnapshots')},
 [ordered]@{axis='legacy_upgrade';assessment='no_new_product_rule_or_cap_change';finding='Existing lost-response retry and truthful renderedUI integration obligations support fixing test acknowledgement. No cap, observer limit, holdout, score, stage deadline, legacy match policy or product implementation change follows from this diagnosis. Preserve priorCCA body lookup and older failure histories separately.';pins=@('requirements','failedHistory')},
 [ordered]@{axis='user_visible_output';assessment='confirmed_real_pending_ui_blocks_next_action';finding='Page7 shows a genuine pending game control with current round2 promptOpen. Native failing locator repeatedly sees disabled input valueLate; exact locator actor is not independently encoded. Test success must include observable frontend acknowledgement rather than HTTP JSON alone. The same boundary exists in matrix ready/choose/answer and strict command/answer; do not silently extend strict four-conflict-only semantics without its approved repair plan.';pins=@('actorSnapshots','native','ui-command-capture.ts:47','live-multiplayer.integration.spec.ts:62-84')}
)
$receipt=[ordered]@{
 recordedAt=(Get-Date).ToString('o');kind='read-only-ten-player-ui-acknowledgement-diagnosis-not-HV';sourceHead='fdee7a2569bb4742e008977e2a9cd7d312def859';runId='0f337bfa-39c7-4650-b35d-6ee8d698be0f';ownSessionId=$manifest.ownSessionId;ownRequestId=$manifest.ownRequestId;parentSessionId=$manifest.parentSessionId;parentRequestId=$manifest.parentRequestId
 preservation=[ordered]@{manifest=Get-Pin $manifestPath;verifiedCopies=$manifest.files.Count;originalPathsRetained=$true;allRetainedCopyHashesMatch=$true;qualification='Original source paths may later change; retained frozen bytes are authoritative. No private runtime settings were copied.'}
 native=[ordered]@{pin=Get-Pin $nativePath;cases=@($native.SelectNodes('//testcase')).Count;passed=@($native.SelectNodes('//testcase[not(failure) and not(error) and not(skipped)]')).Count;failed=@($native.SelectNodes('//testcase[failure or error]')).Count;skipped=@($native.SelectNodes('//testcase[skipped]')).Count;failedPlayers=10;seconds=$failed.time;aggregateOriginals=@('page.waitForRequest timeout30000ms','Your answer disabled timeout30000ms');disabledInputValue='Late';inputIdMeaning='Shared room UUID, not actor identity';sourceStackAnchors=@('ui-command-capture.ts:29','ui-command-capture.ts:43','live-player-counts.integration.spec.ts:148-149');originalFailureTextRetained=$true;errorContext=Get-Pin $contextPath}
 runtime=[ordered]@{pin=Get-Pin $runtimePath;phase=$runtime.phase;completed=$runtime.completed;rounds=$runtime.rounds;uiConfirmedSolves=$runtime.uiSolves;uncertainUiRetries=$runtime.uncertainUiRetries;commandBodyFailures=$runtime.commandBodyFailures;cleanupFailures=$runtime.cleanupFailures;requestFailureTotal=$runtime.requestFailureTotal;diagnosticFailureTotal=$runtime.requestDiagnostics.failureTotal;pendingAtDispose=$runtime.requestDiagnostics.pendingAtDispose;qualification='uiSolves counts driver-observed successful JSON, not proof the frontend retired pending. Final slow-response list includes cleanup reads; all10failure UI snapshots precede cleanup.'}
 actorSnapshots=[ordered]@{pin=Get-Pin $uiPath;actors=$actors;page7=[ordered]@{currentRound=2;stage=1;currentPrompt='Open';pendingGameRetryText=$true;submitAnswerText=$true;solvedScorecardRows=7;pendingEnabled='UNKNOWN';qualification='Player7 identity comes from explicit uiStates index. Any Solved text from another scorecard row is not evidence that page7 itself solved.'}}
 slowAnswerResponses=$slowAnswers;slowSuccessfulAnswerAboveSourceTimeout=[ordered]@{responses=$slowSuccess;frontendSignalTimeoutMs=10000;exactActorCommandJoin='UNKNOWN';causalConclusion='Plausible frontend/driver acknowledgement divergence, not proven by these unjoined timing entries. AbortSignal scheduling and actual transport/body outcome were not recorded peractor.'}
 sourcePins=$sourcePins;confirmedSourceChain=@('pending input is set before fetch and frontend busy, preserved on fetch/body error.','successful driver result.json returns from commitUiCommand before any actual frontend acknowledgement check.','authoritative refresh advances view and clears error but does not clear pending.','input locked is busy OR pending OR confirmed greater than view version; pending alone can block a new-round input.','retry button reuses existing pending object; source idanswer uses room identity only.','new request waiter can time out while action fails before dispatch at disabled-input precondition; current AggregateError preserves both originals.')
 siblingBoundaryAssessment=@(
  [ordered]@{path='matrix commitUi ready/choose/answer';finding='All share driver-only JSON success. Hold original command through observable acknowledgement before advancing/counter increment.'},
  [ordered]@{path='strict command/answer helpers';finding='Also return driver JSON/version. Push+authorizedread proves server projection, not frontend pending retirement. Preserve four-conflict-only semantics unless separately amended in approved test plan.'},
  [ordered]@{path='room-screen mutation/presence';finding='Canonical pending room commands similarly consume bodies before clearing. Current10snapshots show no pending room retry; no room mutation regression is claimed.'},
  [ordered]@{path='future attribution';finding='Body-error-only observer is empty here; observability should bind driver-success/frontend-ack outcome to the original Request identity. Never reconstruct missing historical keys from equal content or timing.'}
 )
 requirements=[ordered]@{effectiveSnapshot=Get-Pin $effectivePath;criteria=$criteria;interpretation='TR09-C01 and TEST109 VERIFY-TR-09 require canonical lost-response retry and authoritative recovery; TR34-C02 covers conflict/retry assertions; TR34-C01/LIVE07 require actual rendered complete games and remain unsatisfied. LIVE05 applies to presence and is not relabeled game support. No new rule/AC/cap or state mutation.'}
 axes=$axes;repairConstraints=@('Require real observable frontend acknowledgement while retaining the exact original command across existing UI pending recovery.','Never treat old pending replay acknowledgement as completion of a newer round/action.','Do not catch arbitrary invoke failures as success or blindly issue new/API requests.','Use independent good/wrong mock controls for driver200/frontendpending, delayedfrontendack, exactcanonicalretry and wrongcommand/noUI rejection before any implementation.','Preserve current capture58 ownership/body/error discrimination, status/conflict rules, deadlines, attempt bounds, cap15, two-answer batches, cleanup and final assertions.','Full frozen suites, all14ordinary UI games and separate strict push plus independent Cline/Beam/High review are still required; a helper gate is not actual-game acceptance.')
 unknowns=@('Exact pending payload/action/round/command ID on page7.','Exact successful11601.008ms response actor/command and whether actual frontend timeout caused page7 pending.','Actual enabled state of pending button in the innerText snapshot.','Exact native locator actor beyond sharedroom DOM id; timing/batch narrative is inference.','Underlying latency/browser/worker/backpressure cause; no measured bottleneck established by this audit.','Success of any proposed repair in actual full matrix/strict/hosted operation.')
 noSourceTestProviderRequirementChanges=$true;testsBuildsModelsRunByThisAgent=$false;accuracy=99;completeness=97;scoreQualification='Bounded source/native evidence diagnosis with explicit missing runtime joins; not hostile approval or release completion.'
}
$jsonPath=Join-Path $folder 'diagnosis.json'
$markdownPath=Join-Path $folder 'diagnosis.md'
$producerPath=Join-Path $folder 'diagnosis-producer.ps1'
if(-not $PSCmdlet.ShouldProcess($folder,'Save safe structured ten-player diagnosis and contextual sibling assessment')){return}
foreach($p in @($jsonPath,$markdownPath,$producerPath)){if(Test-Path -LiteralPath $p){throw 'Refusing to overwrite diagnosis artifact'}}
$receipt | ConvertTo-Json -Depth 40 | Set-Content -LiteralPath $jsonPath -Encoding utf8NoBOM
$markdown=@"
# Ten-player disabled-input diagnosis

$($receipt.recordedAt). Read-only source/evidence diagnosis, not HV.

Frozen fdee7a2 group 0f337bfa-39c7-4650-b35d-6ee8d698be0f failed the ordinary matrix with 8 passed, 1 failed and 5 skipped. The 10-player case lasted 92.434 seconds, reached round 2 and counted 17 driver-side JSON successes. Uncertain retries and driver body-error records are 0; cleanup failures are 0. Native AggregateError preserves the 30-second request waiter timeout and 30-second disabled answer-input failure, whose old value is Late.

All 10 explicit UI snapshots are open, browser/live connected, with the full roster and current round 2. Only page 7 has pending game retry text. Players 0..6 no longer have Submit answer; pages 7..9 do. Page 7 shows prompt Open, Stage 1 and seven solved scorecard rows. Its pending enabled state and exact pending payload remain unknown. The native answer input id uses the shared room UUID, not profile identity, so it cannot identify an actor. Do not label every page solved merely because its scorecard contains solved rows.

The concrete success-criterion gap is in the test chain: commitUiCommand returns immediately on successful driver JSON without requiring frontend acknowledgement. GamePanel retains pending input across fetch/body errors; background refresh can advance authoritative view and clear error while leaving pending intact. Pending alone locks the input. Thus a subsequent action can fail at its enabled-input precondition before producing the matching POST, explaining the shape of the preserved AggregateError without invoking a driver-only cause.

One recorded successful answer response took 11601.008 ms, exceeding the source's 10000 ms AbortSignal duration. This is consistent with possible divergence between driver observation and frontend acknowledgement, but the response has no actor/command/absolute timestamp linkage. The causal join to page 7 is unproved. No measured resource or worker bottleneck is established here. Cleanup 404 reads in the final timing list do not invalidate the earlier full-roster snapshots.

Existing TR09-C01/TEST109 VERIFY-TR-09 canonical lost-response recovery and TR34-C02 conflict/retry verification support a test-only acknowledgement repair. TR34-C01 and LIVE07 still require 14 complete real UI games with 119 participations and 952 solves and remain unsatisfied. LIVE05 is presence-specific. No new product rule, cap reduction or deadline relaxation follows.

The repair should retain the original command until real visible UI acknowledgement, exercising exact canonical pending recovery where present. It must not count an older pending replay as a new round/action, blindly retry arbitrary invoke errors, fabricate status/success, inject API readiness/answers, or weaken solve/cleanup/timeouts. Prove independent same-oracle controls for driver 200/frontend pending and delayed frontend acknowledgement before implementation. Sweep matrix ready/choose/answer and the strict command/answer boundary, preserving strict's existing contract unless the approved plan explicitly amends it. Room mutation/presence is a sibling source pattern; this failure shows no pending room control.

Original 33 lane/source copies were hash-verified and retained. Full safe pins, all 10 actor projections, eight-axis assessment, requirements and exact unknowns are in diagnosis.json. No builds/tests/model/provider/requirements/source changes by this agent. Accuracy 99 and completeness 97 apply only to this bounded diagnosis; exact actor/command/latency cause and actual repair/runtime acceptance remain unknown.
"@
$markdown | Set-Content -LiteralPath $markdownPath -Encoding utf8NoBOM
Copy-Item -LiteralPath $PSCommandPath -Destination $producerPath
if((Get-FileHash -LiteralPath $producerPath).Hash -cne (Get-FileHash -LiteralPath $PSCommandPath).Hash){throw 'Diagnosis producer copy mismatch'}
[ordered]@{recordedAt=(Get-Date).ToString('o');ownSessionId=$receipt.ownSessionId;ownRequestId=$receipt.ownRequestId;outputs=@(Get-Pin $jsonPath;Get-Pin $markdownPath;Get-Pin $producerPath);actors=$actors.Count;axes=$axes.Count;preservedFiles=$manifest.files.Count} | ConvertTo-Json -Depth 6
